public:
    static entity_manager *instance;
    static entity_manager *inst() { return instance; }
    entity *find_entity(const entity_id &, entity_flavor_t, bool = false);
};
enum EventType { SS_CLOSETDOOR_OPEN = 29, SS_CLOSETDOOR_CLOSE = 30 };
class SoundScriptManager {
public:
    static SoundScriptManager *instance;
    static SoundScriptManager *inst() { return instance; }
    int playEvent(EventType, entity * = 0, float = 0.0f);
    void endEvent(int, float = 0.0f);
};

class FEEntityManager {
public:
    entity *surfer_ent; bool mm_anims_loaded; bool all_loaded; float camera_roll_time; int camera_roll_stop;
private:
    int surfer_anim_count; int current_surfer_index; int previous_surfer_index[2]; int loading_surfer_index; int loading_surfer_ent; int surfer_index_2; int current_board_index; FEManager *manager; nglMaterial set_material; float turnaround_length; entity *map; entity *porthole; po porthole_start_po;
public:
    nslEmitterId behindTheCamera; entity *board; entity *my_board; entity *my_board_member; entity *my_rotate_object; entity *my_parent_node;
private:
    bool boards_loaded; bool board_draw; int board_tail_type; entity_anim_tree *board_tree; SSEventId doorEvent; int cam_pos_goal; bool cam_stopped; int cam_stopped_at; float stops[7]; scene_anim_handle_t cam_anim_handle; entity_anim_tree *cam_anim_tree; bool cam_reverse; bool skip_map_zoom; entity *closet_door[2]; float closet_pos[2];
    enum { CLOSET_NOT_MOVING, CLOSET_LEFT_OPENING, CLOSET_LEFT_CLOSING, CLOSET_RIGHT_OPENING, CLOSET_RIGHT_CLOSING };
    float closet_movement; int closet_state; float closet_timer; bool closet_open[2];
public:
    void moveClosetDoor(bool door_left, bool open);
};

